def transform(grid):
    h, w = len(grid), len(grid[0])
    seen=set(); objects=[]
    for r in range(h):
        for c in range(w):
            if grid[r][c] == 0 or (r,c) in seen: continue
            color=grid[r][c]; stack=[(r,c)]; seen.add((r,c)); cells=[]
            while stack:
                x,y=stack.pop(); cells.append((x,y))
                for dx,dy in ((1,0),(-1,0),(0,1),(0,-1)):
                    q=(x+dx,y+dy)
                    if 0<=q[0]<h and 0<=q[1]<w and q not in seen and grid[q[0]][q[1]]==color:
                        seen.add(q); stack.append(q)
            objects.append((color,cells))
    # Move rightmost objects first, repeating to a stable arrangement.
    objects.sort(key=lambda obj:max(c for r,c in obj[1]), reverse=True)
    for _ in range(w):
        changed=False
        for i,(color,cells) in enumerate(objects):
            occupied={(r,c) for j,(_,other) in enumerate(objects) if j!=i for r,c in other}
            shift=0
            while all(c+shift+1<w and (r,c+shift+1) not in occupied for r,c in cells):
                shift+=1
            if shift:
                objects[i]=(color,[(r,c+shift) for r,c in cells]); changed=True
        if not changed: break
    out=[[0]*w for _ in range(h)]
    for color,cells in objects:
        for r,c in cells: out[r][c]=color
    return out

